search_inference_docs.raw_response:
[
  {
    "criterion_id": "find_docs_succeeded",
    "kind": "tool_call_succeeded",
    "required": true,
    "tool_name": "find_docs"
  },
  {
    "criterion_id": "find_examples_succeeded",
    "kind": "tool_call_succeeded",
    "required": false,
    "tool_name": "find_examples"
  },
  {
    "criterion_id": "no_errors",
    "kind": "predicate",
    "required": true,
    "expression": "len(obs.get('errors', [])) == 0"
  },
  {
    "criterion_id": "found_inference_endpoint_docs",
    "kind": "predicate",
    "required": true,
    "expression": "any('inference' in str(r).lower() for r in obs['tool_results'])"
  },
  {
    "criterion_id": "docs_event_emitted",
    "kind": "event",
    "required": false,
    "event_name": "docs_found"
  }
]

metric_drive_loss.raw_response:
[
  {
    "criterion_id": "val_loss_below_0.1",
    "kind": "metric_threshold",
    "required": true,
    "metric": "metrics.val_loss",
    "op": "<",
    "target": 0.1
  },
  {
    "criterion_id": "find_examples_succeeded",
    "kind": "tool_call_succeeded",
    "required": true,
    "tool_name": "find_examples"
  },
  {
    "criterion_id": "no_errors",
    "kind": "predicate",
    "required": false,
    "expression": "len(obs.get('errors', [])) == 0"
  },
  {
    "criterion_id": "has_metrics",
    "kind": "predicate",
